  VALUES 
    (667::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra']::TEXT[], '2026-07-07T00:00:00+00:00'::TIMESTAMPTZ, 'e52d85523b3b2b32081038e079be29b1b8286f2a11e5ac2a24c6deeb59b92b65'::TEXT, ARRAY[2510]::BIGINT[]),
    (667::BIGINT, 'Es el mejor profesor para pasar, no para aprender. Muy relajado (en el buen sentido), cercano a sus estudiantes. Llega tarde a clases, muy flexible con tiempos de entrega y calificación, calificación confusa, falta una mejor guía para que el estudiante realmente aprenda pero es muy buena persona'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, '8c9a01b767de789dc8f8d480244e205380df08230a5dba4707d76c3157e4c777'::TEXT, ARRAY[2510]::BIGINT[]),
    (667::BIGINT, 'Hace muy fácil pasar el curso, explica lo mínimo necesario lo cual no me agrada del todo porque no siento que aprendiera lo suficiente. Trabajos muy cortos, SIEMPRE llega tarde a clase aunque sea virtual. La clase no dura todo el tiempo que dura según horario'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2026-02-11T00:00:00+00:00'::TIMESTAMPTZ, 'f1615df2528332aeec3ab9ade01a9097eac45e2bcb7933970bfea05f7113e678'::TEXT, ARRAY[2520]::BIGINT[]),
    (667::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'c908ea7c91352638d43d54c3e6c629adcf49f05c622274d6ae8fc1a2326992fa'::TEXT, ARRAY[2517]::BIGINT[]),
    (667::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2025-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'a0a1e99a7a37162087863cbd0577509631c9058e5a844a2eb561c210a66653a8'::TEXT, ARRAY[2510]::BIGINT[]),
    (667::BIGINT, 'El profesor en general busca que todos pasen. No da buena retroalimentación en los trabajos, por lo que muchas veces no se sabe si uno hace las cosas de la forma correcta. El profe es un poco vago al revisar trabajos y tarda su rato. Todos pasan si entregan todo. Aprender depende de usted.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muy cómico', 'Da crédito extra']::TEXT[], '2024-12-07T00:00:00+00:00'::TIMESTAMPTZ, '491243058b410e234cc187aad884bc594258c2b86d6f96ae8d5de84ef7197e48'::TEXT, ARRAY[2520]::BIGINT[]),
    (667::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2024-11-24T00:00:00+00:00'::TIMESTAMPTZ, '375d429e77d5ca3ae3ff0f6dce0ab59553bfbee78179e1c81fd83da8e3ad3928'::TEXT, ARRAY[2520]::BIGINT[]),
    (667::BIGINT, 'Muy bueno, aprendí mucho en el curso. El Profe hizo lo posible por ayudar aunque las clases eran asincrónicas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Exámenes retadores']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '05b11a2bdf8aaec7bd8e32638fc0a3a7e58aad6591f58220657a2ace5a85d634'::TEXT, ARRAY[2523]::BIGINT[]),
    (667::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2024-01-10T00:00:00+00:00'::TIMESTAMPTZ, '69f23cee1a52ca6a51989fa27067c49ae3d403f82c76ca84e45bdf745e581aa2'::TEXT, ARRAY[2520]::BIGINT[]),
    (667::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2024-01-03T00:00:00+00:00'::TIMESTAMPTZ, '68d8044cb85886dbe1cbe5c66235351ecfa83203050c6087a004433eb860e5a8'::TEXT, ARRAY[2520]::BIGINT[]),
    (667::BIGINT, 'La verdad, muy desorganizado, califica duro pero no explica suficientemente bien. Dura al dar retroalimentación.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura']::TEXT[], '2024-01-01T00:00:00+00:00'::TIMESTAMPTZ, '3cd933c562fb2cf958fab95d3018b1fc1da9f1a9bf52b73c9d14658df997f18c'::TEXT, ARRAY[2520]::BIGINT[]),
    (667::BIGINT, 'Muy desorganizado en muchos aspectos'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-27T00:00:00+00:00'::TIMESTAMPTZ, '1dde696d394b0d6e90cd86645a5a6cd1f298f20d4aff466fff25e441a2e82117'::TEXT, ARRAY[2520]::BIGINT[]),
    (667::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Muchas tareas']::TEXT[], '2023-11-27T00:00:00+00:00'::TIMESTAMPTZ, '03ac2823e5c1bc42fe64552e7c3426836a9e3d3074f462e49de280ac5bb0f608'::TEXT, ARRAY[2520]::BIGINT[]),
    (667::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-09-06T00:00:00+00:00'::TIMESTAMPTZ, 'f540e2df815deeb25efe5494d14ebded3e18ca9e8bb4c1bc75b94e219e3c2147'::TEXT, ARRAY[2520]::BIGINT[]),
    (667::BIGINT, 'Explica muy bien, califica muy duro.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '02a74866e11bb2e4c13c8292cc944868d8ed7570ac949360b7c70e0ae0efed59'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (667::BIGINT, 'Al final tuvimos que hacer muchísimo brete, a parte el califica duro, mis consejos; haga todas las partis y laboratorios usted. Los quices, proyectos y muchos laboratorios son en parejas así que consígase un/a buen compañero de brete, y no deje nada para lo último, aprenda a ser autodidacta.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '9eb24d3f51c28470418300d119cfcba180db040383e0ade355c57fc374f4f674'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (667::BIGINT, 'Muy buen profesor, siempre va a estar para brindarle toda lla ayuda que pueda dar, califica duro, prepárese bastante para los quices y exámenes, haga todos los trabajos y muy importante, haga los proyectos desde el dia 1, porque se acumula.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '46dbbb6a7159ae61605e77bc9dfe728005e2259ea87372b2dd16b36f3a62edd5'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (667::BIGINT, '10/10'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2023-02-16T00:00:00+00:00'::TIMESTAMPTZ, 'a1980ba5288e110c5fd75319e08e104ea2e6bbe3be4e645edf0b5d369d993244'::TEXT, ARRAY[2520]::BIGINT[]),
    (667::BIGINT, 'Es una muy buena persona, puedes conectar fácilmente con el. Me gustó mucho como dio el curso de requerimientos, pero ya para lo que son progras no me gusta tanto ya que se enreda mucho.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2023-02-15T00:00:00+00:00'::TIMESTAMPTZ, '942ffb726d2d9f70f8ee4b5a732ceeb75638f8c23f6b628d92d05348930a4e1e'::TEXT, ARRAY[2520]::BIGINT[]),
    (667::BIGINT, 'Es una excelente persona, de profe es bueno pero como todos tiene sus cosillas malas, por ejemplo aveces explica enredado pero si usted pregunta le va a ir bien, no tenga miedo a preguntar y elija un buen grupo de trabajo porque el curso es mucho de trabajo en equipo, el profe es muy servicial'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2023-02-02T00:00:00+00:00'::TIMESTAMPTZ, 'aaa935c8d8898b26e6d81748ffd3bab116e849e59843900776198e5f96558f28'::TEXT, ARRAY[2520]::BIGINT[]),
    (667::BIGINT, 'La mejor decisión fue llevar verano con el profe, normalmente este curso es duro en el semestre, pero en verano el profe lo hizo divertido y no tan pesado para no dejar de tener vacaciones, se aprendió y se pasó bien. Llevo este verano en mi corazón'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2023-01-27T00:00:00+00:00'::TIMESTAMPTZ, '592db69bc6f47e7f609576dba6e0eba48b621b20beab1e154082357a75afb47b'::TEXT, ARRAY[2520]::BIGINT[]),
    (667::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2023-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'ec827731f6765802b99e09b48fb851c91c5416de4a29d8014c53dd29406e760d'::TEXT, ARRAY[2520]::BIGINT[]),
    (667::BIGINT, 'Néstor es un buen profe, es muy flexible permite que uno se equivoque pero tiene que poner de su parte, en el tema de programar no es del todo su fuerte entonces hay que tenerle paciencia'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-17T00:00:00+00:00'::TIMESTAMPTZ, 'e093ae4e6c95c0d5e9892bb006df1d8497e01561cfbaf10aad43b8be3ff32622'::TEXT, ARRAY[2517]::BIGINT[]),
    (667::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2022-12-27T00:00:00+00:00'::TIMESTAMPTZ, 'e6ae3defc9a0e17f61ca41de7677f7e604a3cd97eb6dccfc0ebcd1855e1ee041'::TEXT, ARRAY[2517]::BIGINT[]),
    (667::BIGINT, 'Siempre disponible, da mucho apoyo y explica muy bien.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Brinda apoyo']::TEXT[], '2022-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'c2308b23038fb88d18530af37832b0365ed29f274989e9258726ad5f7616830d'::TEXT, ARRAY[2517]::BIGINT[]),
    (667::BIGINT, 'El profesor tiene sus cosas buenas y malas, personalmente no me gusta lo desordenado que es, hay clases que duran solo 30 minutos y empiezan una hora tarde, más que un profesor es como un estudiante más. Nunca le va a entender a la primera las evaluaciones pero al menos responde las dudas.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo']::TEXT[], '2022-11-28T00:00:00+00:00'::TIMESTAMPTZ, '7c406fec54583bd76eb8067957e22c60bc443679a87ab854611e2c690e8cb1ae'::TEXT, ARRAY[2540]::BIGINT[]),
    (667::BIGINT, 'Muy bueno, recomendado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2022-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'd394249fa5939828ac51185a1426695fd9c5a491077677cecfcefdea6937f0bd'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (667::BIGINT, 'Néstor está recomendado, pero para ser la primera vez que da POO, le quedo grande, puras clases asincronicas, pruebas cortas a cada rato, y literal a cada rato, tareas como 25 (en serio), no me gusto, presencial es mejor.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Muchas tareas']::TEXT[], '2022-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'c4155ebd0ec1258dc6c859988e9f1a22d3221dbaa8323c09f0f72c860c655eb0'::TEXT, ARRAY[2527]::BIGINT[]),
    (667::BIGINT, 'Es un profe con mucha vocación, hay que ser muy autodidacta y el profe es exigente pero comprensivo. De los mejores profes sino el mejor de ATI. Los examenes no son practicos y hay muchos trabajos para practicar.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Da crédito extra']::TEXT[], '2022-01-17T00:00:00+00:00'::TIMESTAMPTZ, 'dc287ef9710951350a5a177b4a99f4d22627991eb8e6a66e1747064e7a65baeb'::TEXT, ARRAY[2517]::BIGINT[]),
    (667::BIGINT, 'Es super buen profe, empatiza con los estudiantes y es sumamente comprensivo. Sin embargo, en los exámenes entran algunas cosas que no se vieron a detalle en las clases.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-01T00:00:00+00:00'::TIMESTAMPTZ, '8b9e5af4e2d5c146f0c3526df2afd4b59e4ee79ac0f16b8eeabc0a3bbf98ba36'::TEXT, ARRAY[2520]::BIGINT[]),
    (667::BIGINT, 'Néstor tiene vocación y se interesa por ser buena persona, ambas se ven reflejadas en su labor docente. Se interesa por el aprendizaje del estudiante y es exigente, lo cual implica que uno también tiene que interesarse. Después de 4 cursos con él puedo decir que es un excelente profesor.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-18T00:00:00+00:00'::TIMESTAMPTZ, '17b27ee0e4f3e430501c3fe1ae8cbcaaa48eafac9346caefc1a1281deb8af74b'::TEXT, ARRAY[2512, 2523, 2517, 2520]::BIGINT[]),
    (667::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-09-07T00:00:00+00:00'::TIMESTAMPTZ, '242653343928ef5381f84a18226ced1394c525a2a17ee5a89befb8312074dc95'::TEXT, ARRAY[2510]::BIGINT[]),
    (667::BIGINT, 'Deja muchas tareas mínimo una o dos por semana, es buena nota.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2021-07-17T00:00:00+00:00'::TIMESTAMPTZ, '2cb5066a486b20f5c2671dd8850bfc50947c23c4d4c89736fc403c90ecb7e1fc'::TEXT, ARRAY[2523]::BIGINT[]),
    (667::BIGINT, 'El profe es muy bueno, sabe mucho y se preocupa montones por el estudiante. Él incentiva que el estudiante sea autónomo y autodidacta, así que cuidado si usted no se lleva con eso. Responde a cualquier hora, cualquier día, y le puede ayudar en casi todas las dudas. Totalmente recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '692fe3089c17273deec5a38fb08de9c04f61febef2b98be7db35bb700f55427a'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (667::BIGINT, 'Es de los mejores profes que he tenido, me hizo encontrar gusto para programar. Muchos trabajos en grupo, pone música y es un excelente profe.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2021-07-01T00:00:00+00:00'::TIMESTAMPTZ, '484553cdc4143e10d2df2a57990550df6c48e57f3b83c3dfbd25a1580bb10a70'::TEXT, ARRAY[2512, 2510]::BIGINT[]),
    (667::BIGINT, 'Sus clases son aburridas y se preocupa por dejar prácticas para que entiendan pero no se que tienen que más bien se enreda uno. Te va a dejar solo en los proyectos, pero es una excelente persona, siempre te va a ayudar si tenés un problema y explicar 10 veces, Prepárese para investigar TODO.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Clases largas']::TEXT[], '2021-06-30T00:00:00+00:00'::TIMESTAMPTZ, '2e3dfd8baec1432dea125db5639ddeb2dfb7bcae6222fa9124344a7d5578e537'::TEXT, ARRAY[2523]::BIGINT[]),
    (667::BIGINT, 'Néstor es un profe bastante solidario con el estudiante y sabe negociar para el bien común, sin embargo, sus clases son muy repetitivas y hasta escuetas, no incentiva la participación del estudiante durante estas ni tampoco la aparicion de dudas ya que la materia no es tan explicita.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'f0c49dcc5af34999c7010b9b6ece4a1f86cd83df3b31802a4d3afa892a32e0c2'::TEXT, ARRAY[2523]::BIGINT[]),
    (667::BIGINT, 'Buen profe. Disponible 24/7 (pero hágale sólo preguntas de si o no porque si no, no responde bien jaja) proyecto de investigar mucho y muchísimas tareas'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2021-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'f8eba2ac3f3d020adf989f1c634d0ff6d3601ed7d61ccb44ddfe8bb726e4d52a'::TEXT, ARRAY[2523]::BIGINT[]),
    (667::BIGINT, 'Un crack !'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2021-06-06T00:00:00+00:00'::TIMESTAMPTZ, '118c43a8a1cc0bd24cefd768e2135ce21686a285769cfe0f293d050077b35a46'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (667::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2021-04-12T00:00:00+00:00'::TIMESTAMPTZ, '7fc11ef6f9cfe0bf348c699f7a7c98d67668687d07eb32248133e6cbe447b020'::TEXT, ARRAY[2510, 2512, 2517, 2520, 2523]::BIGINT[]),
    (667::BIGINT, 'De los mejores profes de ATI.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación']::TEXT[], '2021-03-19T00:00:00+00:00'::TIMESTAMPTZ, 'b5bcf19dbb3b2ca971e81c197f15fd5a958afb9b79c37c738847c5c10bb81939'::TEXT, ARRAY[2517]::BIGINT[]),
    (667::BIGINT, 'Todo muy bien :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2021-03-04T00:00:00+00:00'::TIMESTAMPTZ, '9bd8e60f498c0577394b1ac405e8383f3ff0c3e417c26f28242b4018d89b414a'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (667::BIGINT, 'Clases basadas en presentaciones en Power Point y él leyéndolas, mencionar algo extra y saltar diapositivas que él no considera importantes. Los proyectos son fáciles, aunque si tiene algo mal, es posible que no sepa porqué porque no justifica nada.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Muchos proyectos grupales']::TEXT[], '2021-02-10T00:00:00+00:00'::TIMESTAMPTZ, '612aed16ffd6f0137b689209299e96ab2bd66f2bdb9f2141569fcb1d9daacda5'::TEXT, ARRAY[2540]::BIGINT[]),
    (667::BIGINT, 'El profe hace super iterativa la clase y siempre está disponible para dudas por WhatsApp, se aprende bastante con él, peeero los exámenes y proyectos los califica un poco duro, deja bastantes tareas pero fáciles. De igual manera súper recomendado, el curso se puede pasar bien'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '9ba9e69c724bc47070672f486418ed5f33ae0f53a591a5791777e91d8ee8e7fa'::TEXT, ARRAY[2517]::BIGINT[]),
    (667::BIGINT, 'Muy buen profe, fácil, el mejor profe de ATI, tanto presencial como virtual.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, 'd84bda58ff319dd31841578bb466b41582ba61294b83d67287efb41d6ea41924'::TEXT, ARRAY[2520]::BIGINT[]),
    (667::BIGINT, 'Es sumamente confuso a la hora de evaluar. No se sabe qué se falló y no aclara bien tampoco, por lo que esos errores se arrastran. El curso es entretenido, se depende mucho del equipo de trabajo, se nota que al profe le apasiona. Los exámenes van a abarcar todo el día y el profe dura mucho revisando'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-22T00:00:00+00:00'::TIMESTAMPTZ, '300fe5aa8750841175ec3ed29e0cf066aa001528714a5b18c9b3774e492d4c37'::TEXT, ARRAY[2520]::BIGINT[]),
    (667::BIGINT, 'Excelente profesor y sobre todo persona, muy claro en la materia y hace que los estudiantes participen por el mismo buen ambiente que se genera, si puede matricule con él, aunque los criterios de evaluación a veces son un poco confusos.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-16T00:00:00+00:00'::TIMESTAMPTZ, '1a95b14db0afb7bc10e456f69c7f21bf22f0623f6701f33206cc76477a042c41'::TEXT, ARRAY[2520]::BIGINT[]),
    (667::BIGINT, 'Un excelente profe de los mejores del TEC. Si puede meter con el no lo piense...'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2021-01-08T00:00:00+00:00'::TIMESTAMPTZ, '4025a5e87d79d9d5cfbeb221a6f24f6ce8fca007cedc032b6b2d45d1f026b3dc'::TEXT, ARRAY[2517]::BIGINT[]),
    (667::BIGINT, 'Se aprende mucho, se nota que ama lo que hace.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Muchas tareas']::TEXT[], '2020-12-22T00:00:00+00:00'::TIMESTAMPTZ, '36f861ec542975d7037456fc3bbed3b4ba76a3e8346308935581664f4c605449'::TEXT, ARRAY[2520]::BIGINT[]),
    (667::BIGINT, 'Buen profesor, pero no es muy claro a la hora de calificar, no está muy claro que es lo que se falla y a veces es medio contradictorio. Por otro lado, se nota que disfruta la materia y está disponible 24/7 para dudas e incluso se conecta a llamadas.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2020-12-20T00:00:00+00:00'::TIMESTAMPTZ, '3b8db88cbac4d2c88ed3fe5bf0ebdb5010a16cc4d04cb0ddc7b6e1d3ddfa0c14'::TEXT, ARRAY[2520]::BIGINT[]),
