    (667::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2020-08-27T00:00:00+00:00'::TIMESTAMPTZ, '7f74ee1c9f3d12f77b58e8e30f1d6049f7a62d378d54e586449aae7fe44773a9'::TEXT, ARRAY[2510]::BIGINT[]),
    (667::BIGINT, 'El profe es un amor de persona, usted aprende porque aprende, las clases son claras y explica super bien, eso si, califica duro en exámenes, más en los proyectos que el hace. si tiene posibilidad meta con el y no se va a arrepentir. virtual son bastantes examenes asi que no se quede botado'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchos exámenes', 'Clases excelentes']::TEXT[], '2020-08-27T00:00:00+00:00'::TIMESTAMPTZ, '64b49f3a088b921d9a0a1154e2de9b0273f1ff9df51dfeae76a4c81a2b4eb1ca'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (667::BIGINT, 'Los proyectos son imposibles para un primer ingreso, pero siempre busca ayudar y dejar todo claro. Como persona es una teja. Muy recomendado.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2020-08-11T00:00:00+00:00'::TIMESTAMPTZ, '55aee9ba13d1153d0bb7851cd0b2dd2388ce5f419e3b18cf978d75a0398e2d81'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
