    (667::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2020-07-22T00:00:00+00:00'::TIMESTAMPTZ, '5c7c1c1dd7c45bd78ea06497a6cceeea2f07a0ef3fb4c16b4f81052d9c157659'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (667::BIGINT, 'El mejor profe que he tenido, se nota que ama lo que hace. Gran profesional y persona. Califica un toque duro. Chistes tan malos que dan risa :D. Recomendado !!!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases excelentes']::TEXT[], '2020-01-23T00:00:00+00:00'::TIMESTAMPTZ, '0e1b010547434efafdf8025b7e819bf67a51d31acfe2270fbe5cecfc9dd6b104'::TEXT, ARRAY[2517]::BIGINT[]),
    (667::BIGINT, 'El profesor es excelente. Se hacen casos casi todas las semanas, pero son grupales y se aprende bastante con ellos. A veces cuenta chistes muy malos, pero él ya lo sabe.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-12-01T00:00:00+00:00'::TIMESTAMPTZ, '35be0084a21692375ca3584f2103d3bca7f3aead9b09bcbcb19f961377046265'::TEXT, ARRAY[2520]::BIGINT[]),
    (667::BIGINT, 'Si no es el mejor, uno de los mejores profes de ATI. Es egresado de esta carrera, ayuda mucho, los exámenes son duros y califica fuerte pero explica súper bien. Excelente profe, muy recomendado.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, '3086f889de974c4aa72c0ffb834c6a5ed07956d7bb9bf29adb38c0423d7022f5'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (667::BIGINT, 'De los mejores profes que hay en ATI, si usted tiene la oportunidad de matricular con él ni lo piense, es una 100 de persona.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-04T00:00:00+00:00'::TIMESTAMPTZ, 'c9d444e61d144f6b8c12c2a9c78e2dc2b170645ae4dc901f5c0d58c81fb66ba9'::TEXT, ARRAY[2517]::BIGINT[]),
    (667::BIGINT, 'Excelente profe! Explica bien y le importa el estudiante! 10/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Da crédito extra']::TEXT[], '2019-05-22T00:00:00+00:00'::TIMESTAMPTZ, '2042984382c383ddb174ab30224b7316669fc0469fb649bfa008c4f721d4fd3c'::TEXT, ARRAY[2517]::BIGINT[]),
    (667::BIGINT, 'Es uno de los mejores profes que he tenido,si usted tiene dudas sobre algo no importa la hora que sea si usted le envía un mensaje el siempre le responde.Es super buena persona y profesor'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-05-15T00:00:00+00:00'::TIMESTAMPTZ, '4eab7b01c44af1770c107e2005f14c7e5c0370f1f36848a6fd1bd2ec0512b2fe'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (667::BIGINT, 'Es bastante claro y un 10 de persona, el mejor profe. Súper crack. Sabe bastante y siempre intenta ayudar.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-16T00:00:00+00:00'::TIMESTAMPTZ, '3125a06766d2c41011591f11753d338c2fda43cd065570f3a2bb37034bfa435a'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (667::BIGINT, 'El mejor profe que he tenido. Super atento, amable y se nota que le encanta dar clases. Explica muy bien y aunque hay que ponerle no es difícil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-02T00:00:00+00:00'::TIMESTAMPTZ, '1676eefd87178b9641d59ab6352a21fec503838ef4d395516206fa15e4d5ad30'::TEXT, ARRAY[2510]::BIGINT[]),
    (667::BIGINT, 'Es excelente persona y profesor, si tiene la oportunidad de llevar cualquier curso con él, hágalo. Califica bastante duro pero siempre busca a ayudar al estudiante, usted lo puede joder a las 2am y él le ayuda siempre de buen humor. Hay que ponerle bastante a la documentacíon de las progras.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'e027eba5d883fcc4403e0a39bc848e7d73aa64033245277bc1dee89fb27f3bd2'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
