    (667::BIGINT, 'Excelente profesor, muy preparado y sabe mucho. Buenas clases, atento, en cualquier momento y con total disposición atiende dudas. Excelente persona y excelente profesional. Recomendadísimo'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '49ce3e1667c31382b19e87b00266cd4425437b6b8aa331213118646d88d0aff9'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
