    (667::BIGINT, '12/10 súper recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, '394c0ab02936599527246a62a726bb2cca99a9c0bf93f842bf24137701d567b9'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (667::BIGINT, 'Super buena persona, muy buen profe, es mas duro que los otros profes pero si matricula con el intro y taller sale mas preparado que los demas grupos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2018-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'c168928b6573e2ec9444bea0edd49e30c2610f544e845502edc2270560b27152'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
