    (667::BIGINT, 'Chistes malos, excelente persona'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2018-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'a79acd426b27e3221b2e93d80853ab5c05ea9e086e53731bdf7332f80232f146'::TEXT, ARRAY[2512]::BIGINT[]),
