    (667::BIGINT, 'Excelente profe, trata de promover un clima de confianza y alegre durante la clase. Sus examenes son con un nivel más alto en comparación con otros profes, un poco de un razonamiento más alto.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-25T00:00:00+00:00'::TIMESTAMPTZ, '78e381d58917cfb3eb77197db299a4ac9c0aba0fab7218c9b392cb4c5dcbd20e'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (667::BIGINT, 'Es egresado de la propia carrera ATI. Al ser egresado sabe lo complicado que para algunos puede ser el principio de la programación por lo que tiene una paciencia increíble. De verdad que se preocupa por el estudiante. Sus chistes son malísimos pero uno se ríe por lástima jajaja. El mejor profesor!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2018-01-18T00:00:00+00:00'::TIMESTAMPTZ, '2e3f681d94f0c5101b059f2ce5d4c0ab4acdede52d5250dd3a6a89db91fc79d6'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (667::BIGINT, 'Uno de los mejores profes de ATI me alegra que sea un colega con tanta paciencia, interés por el aprendizaje de sus estudiantes En realidad los exámenes no son difíciles.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-14T00:00:00+00:00'::TIMESTAMPTZ, '919a4454fb417c5ca70f1b353bc832d8b53e127625b419366ac28ea78d5b886d'::TEXT, ARRAY[2520]::BIGINT[]),
    (667::BIGINT, 'Excelente profe, explica super claro y lo hace las veces necesarias para que uno entienda la materia, además de que se aprende mucho con él. En consulta es muy pura vida'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-09T00:00:00+00:00'::TIMESTAMPTZ, 'ccefe1050c5a8861209736e6147bab84c09a2c40bb50b574a6bfe1166152c20a'::TEXT, ARRAY[2510]::BIGINT[]),
