    (667::BIGINT, '¡Excelente Profesor! Explica muy bien y es muy interesante. Recomendado 100%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '7d4eeae6a4493cfc921a2748fc7cd4fdcccab555b0d26a6154a3a458bbd9da53'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
